// Defines a property if the property has not been defined yet.
// @ com/google/javascript/jscomp/TypeInference.java:1107
func (t *TypeInference) ensurePropertyDefined(getprop *rhino.Node, rightType jstype.JSType, scope FlowScope) {
	propName := getprop.GetString()
	obj := getprop.GetFirstChild()
	nodeType := GetJSType(obj)
	objectType := ObjectType.Cast(nodeType.RestrictByNotNullOrUndefined())
	propCreationInConstructor := obj.IsThis() && GetJSType(containerScope.GetRootNode()).IsConstructor()
	if objectType == nil {
		registry.RegisterPropertyOnType(propName, nodeType)
	} else {
		if nodeType.IsStruct() && !objectType.HasProperty(propName) {
			staticPropCreation := false
			maybeAssignStm := getprop.GetGrandparent()
			if containerScope.IsGlobal() && NodeUtil.IsPrototypePropertyDeclaration(maybeAssignStm) {
				propCreationFilename := maybeAssignStm.GetSourceFileName()
				ctor := objectType.GetOwnerFunction().GetSource()
				if ctor != nil && ctor.GetSourceFileName().Equals(propCreationFilename) {
					staticPropCreation = true
				}
			}
			if !propCreationInConstructor && !staticPropCreation {
				return
			}
		}
		if EnsurePropertyDeclaredHelper(getprop, objectType, scope) {
			return
		}
		if !objectType.IsPropertyTypeDeclared(propName) {
			if objectType.HasProperty(propName) || !objectType.IsInstanceType() {
				if "prototype".Equals(propName) {
					DefineDeclaredProperty(objectType, propName, rightType, getprop)
				} else {
					objectType.DefineInferredProperty(propName, rightType, getprop)
				}
			} else if propCreationInConstructor {
				objectType.DefineInferredProperty(propName, rightType, getprop)
			} else {
				registry.RegisterPropertyOnType(propName, objectType)
			}
		}
	}
}

