// @ com/google/javascript/jscomp/TypeInference.java:2428
func (t *TypeInference) tightenTypeAfterDereference(n *rhino.Node, scope FlowScope) FlowScope {
	if n.IsQualifiedName() {
		typ := GetJSType(n)
		narrowed := typ.RestrictByNotNullOrUndefined()
		if !typ.Equals(narrowed) {
			scope = NarrowScope(scope, n, narrowed)
		}
	}
	return scope
}

// @ com/google/javascript/jscomp/TypeInference.java:2439
func (t *TypeInference) getPropertyType(objType jstype.JSType, propName string, n *rhino.Node, scope FlowScope) jstype.JSType {
	var propertyType jstype.JSType
	isLocallyInferred := false
	qualifiedName := n.GetQualifiedName()
	v := func() any { if qualifiedName != nil { return scope.GetSlot(qualifiedName) }; return nil }()
	if v != nil {
		varType := v.GetType()
		if varType != nil {
			isDeclared := !v.IsTypeInferred()
			isLocallyInferred = v != GetDeclaredVar(scope, qualifiedName)
			if isDeclared || isLocallyInferred {
				propertyType = varType
			}
		}
	}
	if propertyType == nil && objType != nil {
		foundType := objType.FindPropertyType(propName)
		if foundType != nil {
			propertyType = foundType
		}
	}
	if propertyType == nil || propertyType.IsUnknownType() && qualifiedName != nil {
		regType := ObjectType.Cast(registry.GetType(scope.GetDeclarationScope(), qualifiedName))
		if regType != nil {
			propertyType = regType.GetConstructor()
		}
	}
	if propertyType == nil {
		return unknownType
	} else if propertyType.Equals(unknownType) && isLocallyInferred {
		return GetNativeType(CHECKED_UNKNOWN_TYPE)
	} else {
		return propertyType
	}
}

