// @ com/google/javascript/jscomp/TypeInference.java:2599
func (t *TypeInference) traverseDynamicImport(dynamicImport *rhino.Node, scope FlowScope) FlowScope {
	templateType := registry.GetNativeType(JSTypeNative.UNKNOWN_TYPE)
	moduleMap := compiler.GetModuleMap()
	importSpecifier := dynamicImport.GetFirstChild()
	input := compiler.GetInput(NodeUtil.GetInputId(dynamicImport))
	if importSpecifier.IsStringLit() && moduleMap != nil && input != nil {
		targetPath := input.GetPath().ResolveJsModule(importSpecifier.GetString(), importSpecifier.GetSourceFileName(), importSpecifier.GetLineno(), importSpecifier.GetCharno())
		targetModule := func() any { if targetPath != nil { return moduleMap.GetModule(targetPath) }; return nil }()
		if targetModule != nil {
			scriptNode := targetModule.Metadata().RootNode()
			if scriptNode.HasOneChild() && scriptNode.GetFirstChild().IsModuleBody() {
				exportNamespaceType := func() any { if scriptNode != nil { return scriptNode.GetOnlyChild().GetJSType() }; return nil }()
				if exportNamespaceType != nil {
					templateType = exportNamespaceType
				}
			} else {
				moduleName := NodeUtil.FindPreorder(scriptNode, func(node any) any { return node.MatchesQualifiedName(targetPath.ToModuleName()) }, Predicates.AlwaysTrue())
				if moduleName != nil && moduleName.GetJSType() != nil {
					templateType = moduleName.GetJSType()
				}
			}
		}
	}
	dynamicImport.SetJSType(registry.CreateTemplatizedType(registry.GetNativeObjectType(JSTypeNative.PROMISE_TYPE), templateType))
	return TraverseChildren(dynamicImport, scope)
}

